      function renderMenu() {
        const currentView = normalizeWorkspaceView();
        const items = getWorkspaceNavItems();
        const capabilities = getWorkspaceCapabilities();
        const currentUser = getCurrentUser();
        const displayName =
          String(currentUser?.name || "").trim() ||
          String(session.userEmail || "").trim().split("@")[0] ||
          "there";
        const activeManagedTournament = capabilities.regionalPortalMode
          ? null
          : capabilities.canManageAny
          ? getManagedTournamentForSession()
          : null;
        const groupOrder = ["Home", "Tournament", "People", "Publication", "Regional", "Debater", "Judge", "Tools", "Account", "Settings"];
        const groupedItems = items.reduce((groups, item) => {
          const groupLabel = String(item.group || "Workspace").trim() || "Workspace";
          if (!groups[groupLabel]) {
            groups[groupLabel] = [];
          }
          groups[groupLabel].push(item);
          return groups;
        }, {});
        const orderedGroups = Object.entries(groupedItems).sort((left, right) => {
          const leftOrder = groupOrder.indexOf(left[0]);
          const rightOrder = groupOrder.indexOf(right[0]);
          const a = leftOrder === -1 ? Number.MAX_SAFE_INTEGER : leftOrder;
          const b = rightOrder === -1 ? Number.MAX_SAFE_INTEGER : rightOrder;
          return a - b || String(left[0]).localeCompare(String(right[0]));
        });
        const managerOpsButtons = capabilities.canManageAny && !capabilities.regionalPortalMode && activeManagedTournament
          ? [
              { section: "draw", label: "Round Draw" },
              { section: "draw-review", label: "Draw Review" },
              { section: "results", label: "Standings" },
              hasReleasedBreakBoard(activeManagedTournament)
                ? { section: "breaks", label: "Break" }
                : null,
              { section: "judges", label: "Judges" },
              { section: "motions", label: "Motions" },
              { section: "roster", label: "Teams" },
            ].filter(Boolean)
          : [];

        return `
          <a class="skip-link" href="#workspace-main">Skip to main content</a>
          <aside class="menu-panel" role="navigation" aria-label="Primary workspace navigation">
            <div class="menu-brand">
              <div class="menu-brand-lockup" aria-label="JADE Hummingbird">
                <img class="menu-brand-jade-logo" src="${escapeHtml(
                  JADE_LANDING_LOGO_SRC,
                )}" alt="JADE logo" />
                <p class="menu-brand-name">Hummingbird</p>
              </div>
            </div>
            <div class="inline-card menu-welcome-card">
              ${orderedGroups
                .map(
                  ([groupLabel, groupItems]) => `
                    <div class="menu-side-section ${
                      String(groupLabel || "").trim().toLowerCase() === "tournament"
                        ? "has-section-label"
                        : "is-unlabeled"
                    }">
                      ${
                        String(groupLabel || "").trim().toLowerCase() === "tournament"
                          ? `<span class="theme-section-label">${escapeHtml(groupLabel)}</span>`
                          : ""
                      }
                      <div class="menu-nav-list" role="list">
                        ${groupItems
                          .map(
                            (item) => `
                              <button class="menu-nav-link ${currentView === item.key ? "is-active" : ""}" type="button" data-action="set-view" data-view="${escapeHtml(
                                item.key,
                              )}" aria-current="${currentView === item.key ? "page" : "false"}">
                                <span class="menu-nav-copy">
                                  <strong>${escapeHtml(item.label)}</strong>
                                </span>
                              </button>
                              ${
                                item.key === "tournaments" && managerOpsButtons.length
                                  ? `
                                    <div class="menu-tournament-tools" aria-label="Tournament tools">
                                      ${managerOpsButtons
                                        .map(
                                          (entry) => `
                                            <button class="menu-nav-link menu-operation-link ${
                                              currentView === "tournaments" &&
                                              session.focusedTournamentSection === entry.section
                                                ? "is-active"
                                                : ""
                                            }" type="button" data-action="open-managed-section" data-section="${escapeHtml(
                                              entry.section,
                                            )}">
                                              <span class="menu-nav-copy">
                                                <strong>${escapeHtml(entry.label)}</strong>
                                              </span>
                                            </button>
                                          `,
                                        )
                                        .join("")}
                                    </div>
                                  `
                                  : ""
                              }
                            `,
                          )
                          .join("")}
                        ${
                          String(groupLabel || "").trim().toLowerCase() === "settings"
                            ? `
                                <button class="menu-nav-link" type="button" data-action="logout">
                                  <span class="menu-nav-copy">
                                    <strong>Sign Out</strong>
                                  </span>
                                </button>
                              `
                            : ""
                        }
                      </div>
                    </div>
                  `,
                )
                .join("")}
            </div>
          </aside>
        `;
      }

