      function toggleJudgeSelfCheckIn(tournamentId, allocationId) {
        const tournament = ensureJudgeAccessById(tournamentId);
        if (!tournament) return;

        const allocation = getJudgeAllocationsForTournament(tournament).find(
          (entry) => entry.id === allocationId,
        );
        if (!allocation) {
          setFlash("error", "That judge allocation could not be found.");
          renderApp();
          return;
        }

        if (normalizeEmail(allocation.judgeEmail) !== normalizeEmail(session.userEmail)) {
          setFlash("error", "You can only check in for your own room.");
          renderApp();
          return;
        }

        updateTournament(
          tournamentId,
          (currentTournament) => {
            currentTournament.judgeAllocations = (currentTournament.judgeAllocations || []).map(
              (entry) =>
                entry.id === allocationId
                  ? {
                      ...entry,
                      checkedIn: !entry.checkedIn,
                      checkedInAt: !entry.checkedIn ? timestamp() : "",
                      checkedInAtKey: !entry.checkedIn ? Date.now() : 0,
                    }
                  : entry,
            );
            return addAudit(
              currentTournament,
              (!allocation.checkedIn ? "Judge checked in for " : "Judge removed check-in from ") +
                "Round " +
                allocation.round +
                ", " +
                allocation.room +
                ".",
            );
          },
          allocation.checkedIn ? "Judge check-in removed." : "Judge checked in.",
        );
      }

      function togglePrivateParticipantCheckIn(token, tournamentId, drawId, participantId) {
        const access = findPrivateAccess(token);
        if (!access || access.tournament.id !== tournamentId || access.participant.id !== participantId) {
          setFlash("error", "This private link cannot update that round check-in.");
          renderApp();
          return;
        }

        const drawEntry = getDrawEntryById(access.tournament, drawId);
        if (!drawEntry) {
          setFlash("error", "That round entry could not be found.");
          renderApp();
          return;
        }

        const slot = (Array.isArray(drawEntry.slots) ? drawEntry.slots : []).find((entrySlot) =>
          (Array.isArray(entrySlot.participantIds) ? entrySlot.participantIds : []).includes(
            participantId,
          ),
        );
        const slotKey = slot ? getDrawSlotCheckInKey(slot) : "";
        if (!slotKey) {
          setFlash("error", "Your private link is not attached to that published room.");
          renderApp();
          return;
        }

        const currentlyCheckedIn = Boolean(drawEntry.entryCheckIns?.[slotKey]);
        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.draw = (tournament.draw || []).map((entry) =>
              entry.id === drawId
                ? {
                    ...entry,
                    entryCheckIns: {
                      ...(entry.entryCheckIns || {}),
                      [slotKey]: !currentlyCheckedIn,
                    },
                  }
                : entry,
            );
            return addAudit(
              tournament,
              (currentlyCheckedIn ? "Removed check-in for " : "Recorded check-in for ") +
                access.participant.name +
                " in Round " +
                drawEntry.round +
                ", " +
                drawEntry.room +
                ".",
            );
          },
          currentlyCheckedIn ? "Round check-in removed." : "You are checked in for this round.",
          {
            forceCloud: true,
            errorMessage: "Your round check-in could not be synced to the shared backend.",
          },
        );
      }

      function generateTournamentDraw(tournamentId, formData) {
        const tournament = ensureTournamentManagerById(tournamentId);
        if (!tournament) return;
        const drawIntent = String(formData.get("intent") || "").trim().toLowerCase();
        const previewOnly = drawIntent === "preview";
        const round = normalizeRoundCount(formData.get("round"), 1);
        const roundProfile = getRoundProfileForRound(tournament, round);
        const rawMethod = normalizeDrawMethodChoice(formData.get("method"), "auto");
        const method = getResolvedDrawMethod(tournament, roundProfile, rawMethod);
        const requestedRoomSize = normalizeOptionalCount(
          optionalNumberFromForm(formData, "teamsPerRoom", null),
          normalizeOptionalCount(
            roundProfile.teamsPerRoom,
            normalizeOptionalCount(tournament.config.teamsPerRoom, 2),
          ),
          8,
        );
        const previewPlan = getDrawGenerationPlan(
          tournament,
          roundProfile,
          method,
          requestedRoomSize,
        );
        if (previewPlan.error) {
          setFlash("error", previewPlan.error);
          renderApp();
          return;
        }
        const previewStructure = getEffectiveRoundStructure(tournament, roundProfile, {
          roomSizeOverride: requestedRoomSize,
          allowRoomOverride: true,
        });
        const previewRoomSize = Math.max(1, Number(previewStructure.teamsPerRoom) || 1);
        const previewHasOverflow =
          previewPlan.overflowParticipants.length > 0 ||
          previewPlan.entries.length % previewRoomSize !== 0;
        if (previewPlan.entries.length < previewRoomSize) {
          setFlash(
            "error",
            shouldGenerateSpeakerPairingTeams(tournament, roundProfile)
              ? "Add enough speakers to build at least one full room from this round configuration."
              : "Add enough complete entries to build at least one full room before generating a draw.",
          );
          renderApp();
          return;
        }

        updateTournament(
          tournamentId,
          (tournament) => {
            const round = normalizeRoundCount(formData.get("round"), 1);
            const roundProfile = getRoundProfileForRound(tournament, round);
            const rawMethod = normalizeDrawMethodChoice(formData.get("method"), "auto");
            const method = getResolvedDrawMethod(tournament, roundProfile, rawMethod);
            const generationPlan = getDrawGenerationPlan(
              tournament,
              roundProfile,
              method,
              requestedRoomSize,
            );
            const effectiveStructure = getEffectiveRoundStructure(tournament, roundProfile, {
              roomSizeOverride: requestedRoomSize,
              allowRoomOverride: true,
            });
            const roomSize = Math.max(
              1,
              Number(effectiveStructure.teamsPerRoom) || Number(generationPlan.roomSize) || 2,
            );
            const roomPrefix = String(formData.get("roomPrefix") || "Room").trim() || "Room";
            const roomStart = Math.max(1, numberFromForm(formData, "roomStart", 1));
            const releaseNow = previewOnly ? false : boolFromForm(formData, "releaseNow");
            let entries = generationPlan.entries;

            if (method === "random") {
              entries = shuffleEntries(entries);
            } else {
              entries = [...entries].sort((left, right) =>
                compareDrawEntries(tournament, left, right),
              );
              if (method === "fold") {
                entries = foldEntries(entries);
              }
            }

            const safeRoomSize = Math.max(1, Number(roomSize) || 2);
            const fullEntryCount = Math.floor(entries.length / safeRoomSize) * safeRoomSize;
            const groups = chunkEntries(entries.slice(0, fullEntryCount), safeRoomSize);
            const overflowEntries = entries.slice(fullEntryCount);
            const overflowParticipants = generationPlan.overflowParticipants || [];
            const hasOverflow = overflowEntries.length > 0 || overflowParticipants.length > 0;
            tournament.draw = (tournament.draw || []).filter(
              (entry) => Number(entry.round) !== Number(round),
            );
            tournament.judgeAllocations = (tournament.judgeAllocations || []).filter(
              (allocation) => Number(allocation.round) !== Number(round),
            );
            tournament.draw.push(
              ...groups.map((group, index) =>
                createDrawRecord(tournament, {
                  round,
                  room: roomPrefix + " " + (roomStart + index),
                  status: releaseNow ? "Published" : "Draft",
                  priority: getAutoPriorityValue(index, groups.length, method),
                  entries: group,
                }),
              ),
            );
            if (hasOverflow) {
              tournament.draw.push(
                createDrawRecord(tournament, {
                  round,
                  room: roomPrefix + " " + (roomStart + groups.length) + " Overflow",
                  status: "Draft",
                  priority: 1,
                  matchup: formatOverflowDrawMatchup(overflowEntries, overflowParticipants),
                  disableMatchupInference: true,
                  entryIds: overflowEntries
                    .map((entry) => String(entry.id || "").trim())
                    .filter(Boolean),
                  teamIds: overflowEntries
                    .map((entry) => getDrawEntryTeamId(entry))
                    .filter(Boolean),
                  participantIds: Array.from(
                    new Set(
                      overflowEntries
                        .flatMap((entry) => getDrawEntryParticipantIds(entry))
                        .concat(
                          overflowParticipants
                            .map((participant) => String(participant?.id || "").trim())
                            .filter(Boolean),
                        ),
                    ),
                  ),
                }),
              );
            }
            tournament.draw = tournament.draw.sort(
              (left, right) => Number(left.round) - Number(right.round),
            );
            return addAudit(
              tournament,
              "Generated a " +
                method +
                " draw for Round " +
                round +
                (isOutroundProfile(roundProfile) && generationPlan.sourceLabel
                  ? " using the " + generationPlan.sourceLabel.toLowerCase()
                  : "") +
                (releaseNow ? " and released it." : " as a draft.") +
                (hasOverflow ? " Overflow entries were left in a separate draft room." : ""),
            );
          },
          previewOnly
            ? previewHasOverflow
              ? "Draw preview saved as draft. Overflow entries were left in a separate draft room."
              : "Draw preview saved as draft."
            : previewHasOverflow
              ? "Round draw generated. Overflow entries were left in a separate draft room."
              : "Round draw generated.",
          {
            forceCloud: true,
            errorMessage: "The generated draw could not be synced to the shared backend.",
          },
        );
      }

      function releaseDrawRound(tournamentId, roundValue) {
        const tournament = ensureTournamentManagerById(tournamentId);
        if (!tournament) return;
        const round = normalizeRoundCount(roundValue, 1);
        if (!(tournament.draw || []).some((entry) => Number(entry.round) === Number(round))) {
          setFlash("error", "There are no rooms saved for that round yet.");
          renderApp();
          return;
        }
        const conflictSummary = getRoundConflictSummary(tournament, round);

        updateTournament(
          tournamentId,
          (tournament) => {
            let changed = false;
            tournament.draw = (tournament.draw || []).map((entry) => {
              if (Number(entry.round) === Number(round)) {
                changed = true;
                return {
                  ...entry,
                  status: "Published",
                  publishedAt: entry.publishedAt || timestamp(),
                  publishedAtKey:
                    normalizeTimestampKey(entry.publishedAtKey, entry.publishedAt) || Date.now(),
                };
              }
              return entry;
            });
            if (!changed) {
              return tournament;
            }
            return addAudit(tournament, "Released the draw for Round " + round + ".");
          },
          conflictSummary.total
            ? "Round released with " +
                conflictSummary.total +
                " flagged conflict" +
                (conflictSummary.total === 1 ? "" : "s") +
                " to review."
            : "Round released.",
          {
            forceCloud: true,
            errorMessage: "The round release could not be synced to the shared backend.",
          },
        );
      }

      function clearDrawRound(tournamentId, roundValue) {
        const tournament = ensureTournamentManagerById(tournamentId);
        if (!tournament) return;
        const round = normalizeRoundCount(roundValue, 1);
        if (!(tournament.draw || []).some((entry) => Number(entry.round) === Number(round))) {
          setFlash("error", "There is no saved draw for that round.");
          renderApp();
          return;
        }

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.draw = (tournament.draw || []).filter(
              (entry) => Number(entry.round) !== Number(round),
            );
            tournament.judgeAllocations = (tournament.judgeAllocations || []).filter(
              (allocation) => Number(allocation.round) !== Number(round),
            );
            return addAudit(tournament, "Cleared the draw for Round " + round + ".");
          },
          "Round draw cleared.",
          {
            forceCloud: true,
            errorMessage: "The round clear could not be synced to the shared backend.",
          },
        );
      }

      function deleteTeam(tournamentId, teamId) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            const target = (tournament.teams || []).find((team) => team.id === teamId);
            tournament.teams = (tournament.teams || []).filter((team) => team.id !== teamId);
            tournament.participants = (tournament.participants || []).map((participant) => {
              if (participant.teamId === teamId) {
                return {
                  ...participant,
                  teamId: "",
                  teamName: "",
                };
              }
              return participant;
            });
            return addAudit(
              tournament,
              "Removed team " + (target ? getTeamDisplayLabel(target) : teamId) + ".",
            );
          },
          "Team removed.",
          {
            forceCloud: true,
            errorMessage: "The team removal could not be synced to the shared backend.",
          },
        );
      }

      function deleteParticipant(tournamentId, participantId) {
        const tournament = ensureTournamentManagerById(tournamentId);
        if (!tournament) return;
        const target = tournament.participants.find((entry) => entry.id === participantId);
        if (target?.email) {
          rememberTournamentHistoryForEmail(target.email, tournament.id);
        }

        updateTournament(
          tournamentId,
          (tournament) => {
            const target = tournament.participants.find((entry) => entry.id === participantId);
            tournament.participants = tournament.participants.filter(
              (entry) => entry.id !== participantId,
            );
            if (target) {
              tournament.permissions.debaterEmails = tournament.permissions.debaterEmails.filter(
                (email) =>
                  email !== target.email ||
                  tournament.participants.some((entry) => entry.email === target.email),
              );
            }
            return addAudit(tournament, "Removed participant " + (target?.name || participantId) + ".");
          },
          "Participant removed.",
          {
            forceCloud: true,
            errorMessage: "The participant removal could not be synced to the shared backend.",
          },
        );
      }

      function rotatePrivateLink(tournamentId, participantId) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.participants = tournament.participants.map((participant) =>
              participant.id === participantId
                ? {
                    ...participant,
                    token: createId("token"),
                  }
                : participant,
            );
            return addAudit(tournament, "Rotated a private link token.");
          },
          "Private link rotated.",
        );
      }

      function addStanding(tournamentId, formData) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.standings.push(
              createStandingRecord(
                String(formData.get("name") || "").trim(),
                buildStandingMetricsFromForm(tournament, formData),
              ),
            );
            tournament.standings = sortStandingsForTournament(tournament.standings, tournament);
            return addAudit(tournament, "Added or updated a standings row.");
          },
          "Standings row added.",
        );
      }

      function deleteStanding(tournamentId, standingId) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.standings = tournament.standings
              .filter((entry) => entry.id !== standingId);
            tournament.standings = sortStandingsForTournament(tournament.standings, tournament);
            return addAudit(tournament, "Deleted a standings row.");
          },
          "Standings row deleted.",
          {
            forceCloud: true,
            errorMessage:
              "The standings deletion could not be synced to the shared backend.",
          },
        );
      }

      function addDrawRow(tournamentId, formData) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.draw.push(
              createDrawRecord(tournament, {
                round: numberFromForm(formData, "round", 1),
                room: String(formData.get("room") || "").trim(),
                matchup: String(formData.get("matchup") || "").trim(),
                status: String(formData.get("status") || "Published").trim(),
                priority: normalizeRoomPriority(formData.get("priority"), 3),
              }),
            );
            tournament.draw = tournament.draw.sort((a, b) => Number(a.round) - Number(b.round));
            return addAudit(tournament, "Posted a draw row.");
          },
          "Draw row posted.",
          {
            forceCloud: true,
            errorMessage: "The draw row could not be synced to the shared backend.",
          },
        );
      }

      function deleteDrawRow(tournamentId, drawId) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.draw = tournament.draw.filter((entry) => entry.id !== drawId);
            tournament.judgeAllocations = (tournament.judgeAllocations || []).filter(
              (allocation) => allocation.drawId !== drawId,
            );
            return addAudit(tournament, "Deleted a draw row.");
          },
          "Draw row deleted.",
          {
            forceCloud: true,
            errorMessage: "The draw row deletion could not be synced to the shared backend.",
          },
        );
      }

      function toggleTournamentStatus(tournamentId) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.status = tournament.status === "open" ? "closed" : "open";
            return addAudit(tournament, "Tournament status changed to " + tournament.status + ".");
          },
          "Tournament status updated.",
        );
      }

      function toggleTournamentField(tournamentId, field) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.publication[field] = !tournament.publication[field];
            return addAudit(tournament, "Toggled " + field + " to " + tournament.publication[field] + ".");
          },
          "Tournament publishing updated.",
        );
      }

      function setTournamentPublicationField(tournamentId, field, targetValue, successMessage) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            const desiredValue = Boolean(targetValue);
            if (Boolean(tournament.publication[field]) === desiredValue) {
              return tournament;
            }
            tournament.publication[field] = desiredValue;
            return addAudit(
              tournament,
              "Set " + field + " to " + tournament.publication[field] + ".",
            );
          },
          successMessage || "Tournament publishing updated.",
        );
      }

      function closeTournament(tournamentId) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            if (tournament.status === "archived") {
              return tournament;
            }
            tournament.status = "closed";
            return addAudit(tournament, "Tournament status changed to closed.");
          },
          "Tournament closed.",
        );
      }

      function archiveTournament(tournamentId) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            tournament.status = "archived";
            tournament.publication.dashboardListed = false;
            return addAudit(tournament, "Tournament archived.");
          },
          "Tournament archived.",
          {
            forceCloud: true,
            errorMessage: "The archive action could not be synced to the shared backend.",
          },
        );
      }

      function generateRandomTeams(tournamentId) {
        if (!ensureTournamentManagerById(tournamentId)) return;

        updateTournament(
          tournamentId,
          (tournament) => {
            if (!tournament.config.randomTeamsAllowed) {
              return tournament;
            }

            const participants = clone(tournament.participants);
            for (let index = participants.length - 1; index > 0; index -= 1) {
              const swapIndex = Math.floor(Math.random() * (index + 1));
              const temp = participants[index];
              participants[index] = participants[swapIndex];
              participants[swapIndex] = temp;
            }

            const teamSize = Math.max(
              1,
              Number(getRoundProfileForRound(tournament, 1).teamSize) ||
                Number(tournament.config.teamSize) ||
                1,
            );
            const generatedTeams = [];
            tournament.participants = participants.map((participant, index) => {
              const teamNumber = Math.floor(index / teamSize) + 1;
              let generatedTeam = generatedTeams[teamNumber - 1];
              if (!generatedTeam) {
                generatedTeam = createTeamRecord(tournament.code + " Random Team " + teamNumber, "", {
                  notes: "Randomly generated team.",
                  source: "generated",
                });
                generatedTeams.push(generatedTeam);
              }
              return {
                ...participant,
                teamId: generatedTeam.id,
                teamName: generatedTeam.name,
              };
            });
            tournament.teams = [
              ...(tournament.teams || []).filter(
                (team) => !String(team.name || "").startsWith(tournament.code + " Random Team "),
              ),
              ...generatedTeams,
            ];
            synchronizeTournamentTeamReferences(tournament);

            return addAudit(tournament, "Generated random teams for eligible participants.");
          },
          "Random teams generated.",
        );
      }

      function submitJudgeBallot(tournamentId, allocationId, formData) {
        const tournament = ensureJudgeAccessById(tournamentId);
        if (!tournament) return;

        const targetAllocation = getJudgeAllocationsForTournament(tournament).find(
          (allocation) => allocation.id === allocationId,
        );
        if (!targetAllocation) {
          setFlash("error", "That judge allocation could not be found.");
          renderApp();
          return;
        }

        const actingJudgeEmail = normalizeEmail(session.userEmail);
        if (normalizeEmail(targetAllocation.judgeEmail) !== actingJudgeEmail) {
          setFlash("error", "You can only submit ballots for your own judge allocations.");
          renderApp();
          return;
        }

        const canSubmitBallot = canJudgeAllocationSubmitBallot(tournament, targetAllocation);
        const isChair = normalizeJudgeAllocationRole(targetAllocation.panelRole, "panelist") === "chair";
        if (!canSubmitBallot) {
          setFlash("error", "Only the assigned chair can submit the official ballot for that room.");
          renderApp();
          return;
        }

        if (targetAllocation.submittedAt) {
          setFlash(
            "error",
            "That ballot has already been submitted and locked. Only a tournament manager can reopen it.",
          );
          renderApp();
          return;
        }

        const targetDrawEntry = getDrawEntryById(tournament, targetAllocation.drawId);
        const roomSlots = Array.isArray(targetDrawEntry?.slots) ? targetDrawEntry.slots : [];
        const resultMode = getDrawOfficialResultMode(tournament, targetDrawEntry);
        let officialResults = {};

        if (isChair && resultMode === "bp_rank" && roomSlots.length) {
          const roomPlacements = roomSlots.map((slot) => {
            const slotKey = getDrawSlotCheckInKey(slot);
            return {
              slotKey,
              rank: normalizeOptionalCount(
                formData.get(getJudgeRoomResultFieldName(slotKey)),
                null,
                roomSlots.length,
              ),
            };
          });

          if (roomPlacements.some((entry) => !entry.rank)) {
            setFlash("error", "Every team in the room needs an official placement before the ballot can be submitted.");
            renderApp();
            return;
          }

          if (new Set(roomPlacements.map((entry) => entry.rank)).size !== roomPlacements.length) {
            setFlash("error", "Each BP team needs a unique room placement.");
            renderApp();
            return;
          }

          officialResults = roomPlacements.reduce((result, entry) => {
            result[entry.slotKey] = { rank: entry.rank };
            return result;
          }, {});
        }

        if (isChair && resultMode === "win_loss" && roomSlots.length) {
          const roomOutcomes = roomSlots.map((slot) => {
            const slotKey = getDrawSlotCheckInKey(slot);
            return {
              slotKey,
              outcome: String(
                formData.get(getJudgeRoomResultFieldName(slotKey)) || "",
              ).trim().toLowerCase(),
            };
          });

          if (roomOutcomes.some((entry) => !["win", "loss"].includes(entry.outcome))) {
            setFlash("error", "Every side in the room needs an official win or loss result before the ballot can be submitted.");
            renderApp();
            return;
          }

          if (roomSlots.length === 2) {
            const wins = roomOutcomes.filter((entry) => entry.outcome === "win").length;
            const losses = roomOutcomes.filter((entry) => entry.outcome === "loss").length;
            if (wins !== 1 || losses !== 1) {
              setFlash("error", "Two-side rooms need exactly one winning side and one losing side.");
              renderApp();
              return;
            }
          }

          officialResults = roomOutcomes.reduce((result, entry) => {
            result[entry.slotKey] = { outcome: entry.outcome };
            return result;
          }, {});
        }

        const participantIds =
          targetAllocation.participantIds?.length
            ? targetAllocation.participantIds
            : getParticipantsForDrawRecord(
                tournament,
                getDrawEntryById(tournament, targetAllocation.drawId),
              ).map((participant) => participant.id);
        const optionalScoreConfig = getRoundOptionalScoreConfig(
          tournament,
          targetAllocation.round,
        );

        const missingSpeakerScore = participantIds.some((participantId) => {
          return (
            parseBallotScoreValue(
              formData.get(getJudgeScoreFieldName(participantId, "Speaker Score")),
            ) === null
          );
        });

        if (missingSpeakerScore) {
          setFlash("error", "Every adjudicated speaker needs a speaker score before the ballot can be submitted.");
          renderApp();
          return;
        }

        updateTournament(
          tournamentId,
          (currentTournament) => {
            const submittedAt = timestamp();
            const submittedAtKey = Date.now();
            currentTournament.participants = (currentTournament.participants || []).map(
              (participant) => {
                if (!participantIds.includes(participant.id)) {
                  return participant;
                }

                const speakerScore =
                  parseBallotScoreValue(
                    formData.get(getJudgeScoreFieldName(participant.id, "Speaker Score")),
                  ) ?? 0;
                const scores = {
                  "Speaker Score": speakerScore,
                };

                (currentTournament.settings.feedbackCategories || []).forEach((category) => {
                  const rawValue = parseBallotScoreValue(
                    formData.get(getJudgeScoreFieldName(participant.id, category)),
                  );
                  if (rawValue !== null) {
                    scores[category] = rawValue;
                  }
                });

                if (optionalScoreConfig.crossExaminationEnabled) {
                  const questionValue = parseBallotScoreValue(
                    formData.get(getJudgeCrossQuestionFieldName(participant.id)),
                  );
                  const responseValue = parseBallotScoreValue(
                    formData.get(getJudgeCrossResponseFieldName(participant.id)),
                  );
                  if (questionValue !== null) {
                    scores["Cross Examination Questions"] = questionValue;
                  }
                  if (responseValue !== null) {
                    scores["Cross Examination Responses"] = responseValue;
                  }
                }

                if (optionalScoreConfig.rebuttalEnabled) {
                  const rebuttalValue = parseBallotScoreValue(
                    formData.get(getJudgeRebuttalFieldName(participant.id)),
                  );
                  if (rebuttalValue !== null) {
                    scores.Rebuttal = rebuttalValue;
                  }
                }

                const nextEntry = {
                  id:
                    getExistingJudgeFeedback(
                      participant,
                      targetAllocation.id,
                      targetAllocation.judgeEmail,
                    )?.id || createId("feedback"),
                  allocationId: targetAllocation.id,
                  drawId: targetAllocation.drawId,
                  round: targetAllocation.round,
                  judgeEmail: normalizeEmail(targetAllocation.judgeEmail),
                  speakerScore,
                  scores,
                  note: String(
                    formData.get(getJudgeNoteFieldName(participant.id)) || "",
                  ).trim(),
                  createdAt: submittedAt,
                };

                return {
                  ...participant,
                  feedback: [
                    ...(participant.feedback || []).filter(
                      (entry) =>
                        !(
                          String(entry.allocationId || "") === String(targetAllocation.id) &&
                          normalizeEmail(entry.judgeEmail) ===
                    normalizeEmail(targetAllocation.judgeEmail)
                        ),
                    ),
                    nextEntry,
                  ],
                };
              },
            );

            currentTournament.judgeAllocations = (currentTournament.judgeAllocations || []).map(
              (allocation) =>
                allocation.id === targetAllocation.id
                  ? {
                      ...allocation,
                      status: "submitted",
                      checkedIn: true,
                      checkedInAt: allocation.checkedInAt || submittedAt,
                      checkedInAtKey:
                        normalizeTimestampKey(allocation.checkedInAtKey, allocation.checkedInAt) ||
                        submittedAtKey,
                      submittedAt,
                      submittedAtKey,
                    }
                  : allocation,
            );
            currentTournament.draw = (currentTournament.draw || []).map((entry) =>
              entry.id === targetAllocation.drawId
                ? {
                    ...entry,
                    officialResults:
                      isChair && resultMode !== "speaker_only"
                        ? normalizeDrawOfficialResults(officialResults)
                        : normalizeDrawOfficialResults(entry.officialResults),
                    ballotCheckedIn: true,
                  }
                : entry,
            );

            return addAudit(
              currentTournament,
              "Judge ballot submitted for Round " +
                targetAllocation.round +
                ", " +
                targetAllocation.room +
                ".",
            );
          },
          "Judge ballot submitted.",
        );
      }

      function submitParticipantJudgeFeedback(tournamentId, participantId, allocationId, formData) {
        const tournament = getTournamentById(tournamentId);
        const participant = tournament ? getParticipantById(tournament, participantId) : null;
        const allocation = tournament
          ? getJudgeAllocationsForTournament(tournament).find(
              (entry) => String(entry.id || "").trim() === String(allocationId || "").trim(),
            )
          : null;
        if (!tournament || !participant || !allocation) {
          setFlash("error", "That judge feedback target could not be found.");
          renderApp();
          return;
        }
        if (normalizeJudgeAllocationRole(allocation.panelRole, "panelist") !== "chair") {
          setFlash("error", "Debater feedback is only available for the assigned chair.");
          renderApp();
          return;
        }
        const rating = parseFeedbackRating(formData.get("rating"), null, 1, 10);
        const note = String(formData.get("note") || "").trim();
        if (rating === null) {
          setFlash("error", "Please enter a call score from 1 to 10.");
          renderApp();
          return;
        }
        if (!note) {
          setFlash("error", "Please include written feedback about the chair call.");
          renderApp();
          return;
        }

        updateTournament(
          tournamentId,
          (currentTournament) => {
            const judge = getJudgeByEmail(currentTournament, allocation.judgeEmail);
            currentTournament.feedbackLedger = [
              normalizeTournamentFeedbackLedgerEntry({
                type: "team_to_chair",
                tournamentId,
                drawId: allocation.drawId,
                allocationId: allocation.id,
                round: allocation.round,
                room: allocation.room,
                sourceEmail: participant.email,
                sourceName: participant.name,
                targetEmail: allocation.judgeEmail,
                targetName: judge?.name || allocation.judgeEmail,
                participantId: participant.id,
                participantName: participant.name,
                teamName: String(formData.get("teamName") || participant.teamName || participant.name).trim(),
                institution: participant.institution,
                rating,
                note,
                visibility: "manager_only",
              }),
              ...(currentTournament.feedbackLedger || []),
            ].slice(0, 1000);
            return addAudit(
              currentTournament,
              "A participant feedback note was submitted about adjudication in Round " +
                allocation.round +
                ", " +
                allocation.room +
                ".",
            );
          },
          "Judge feedback sent to tournament managers.",
        );
      }

      function submitJudgePeerFeedback(
        tournamentId,
        allocationId,
        targetAllocationId,
        feedbackType,
        formData,
      ) {
        const tournament = ensureJudgeAccessById(tournamentId);
        if (!tournament) return;
        const allocation = getJudgeAllocationsForTournament(tournament).find(
          (entry) => String(entry.id || "").trim() === String(allocationId || "").trim(),
        );
        const targetAllocation = getJudgeAllocationsForTournament(tournament).find(
          (entry) => String(entry.id || "").trim() === String(targetAllocationId || "").trim(),
        );
        if (!allocation || !targetAllocation) {
          setFlash("error", "That judge feedback target could not be found.");
          renderApp();
          return;
        }
        if (normalizeEmail(allocation.judgeEmail) !== normalizeEmail(session.userEmail)) {
          setFlash("error", "You can only submit manager-only adjudication feedback for your own assignment.");
          renderApp();
          return;
        }
        const rating = parseFeedbackRating(formData.get("rating"), null, 1, 10);
        const note = String(formData.get("note") || "").trim();
        if (rating === null) {
          setFlash("error", "Please enter a call score from 1 to 10.");
          renderApp();
          return;
        }
        if (!note) {
          setFlash("error", "Please include written feedback about the call.");
          renderApp();
          return;
        }
        const sourceRole = normalizeJudgeAllocationRole(allocation.panelRole, "panelist");
        const targetRole = normalizeJudgeAllocationRole(targetAllocation.panelRole, "panelist");
        if (
          (String(feedbackType || "").trim() === "chair_to_wing" &&
            !(sourceRole === "chair" && targetRole !== "chair")) ||
          (String(feedbackType || "").trim() === "wing_to_chair" &&
            !(sourceRole !== "chair" && targetRole === "chair"))
        ) {
          setFlash("error", "This feedback flow only supports chair-to-wing or wing-to-chair call reviews.");
          renderApp();
          return;
        }

        updateTournament(
          tournamentId,
          (currentTournament) => {
            const sourceJudge = getJudgeByEmail(currentTournament, allocation.judgeEmail);
            const targetJudge = getJudgeByEmail(currentTournament, targetAllocation.judgeEmail);
            currentTournament.feedbackLedger = [
              normalizeTournamentFeedbackLedgerEntry({
                type: String(feedbackType || "wing_to_chair").trim(),
                tournamentId,
                drawId: allocation.drawId,
                allocationId: targetAllocation.id,
                round: allocation.round,
                room: allocation.room,
                sourceEmail: allocation.judgeEmail,
                sourceName: sourceJudge?.name || allocation.judgeEmail,
                targetEmail: targetAllocation.judgeEmail,
                targetName: String(formData.get("targetName") || targetJudge?.name || targetAllocation.judgeEmail).trim(),
                rating,
                note,
                visibility: "manager_only",
              }),
              ...(currentTournament.feedbackLedger || []),
            ].slice(0, 1000);
            return addAudit(
              currentTournament,
              "A manager-only adjudication feedback note was submitted for Round " +
                allocation.round +
                ", " +
                allocation.room +
                ".",
            );
          },
          "Manager-only adjudication feedback saved.",
        );
      }

      function updateUserRole(email, formData) {
        if (!canAccessGlobalSettings()) {
          setFlash("error", "Only System Managers can change global roles.");
          renderApp();
          return;
        }

        const target = normalizeEmail(email);
        const role = normalizeGlobalRole(formData.get("globalRole") || "member");
        if (
          isProtectedSystemManagerEmail(target) &&
          !["manager", "system_admin"].includes(role)
        ) {
          setFlash("error", "The last active System Manager cannot be demoted.");
          renderApp();
          return;
        }
        state.users = state.users.map((user) =>
          user.email === target ? { ...user, globalRole: role } : user,
        );
        persist("success", "User role updated.");
      }

      async function toggleUserActive(email) {
        if (!canAccessGlobalSettings()) {
          setFlash("error", "Only System Managers can enable or disable accounts.");
          renderApp();
          return;
        }

        const target = normalizeEmail(email);
        if (isProtectedSystemManagerEmail(target)) {
          setFlash("error", "The last active System Manager cannot be disabled.");
          renderApp();
          return;
        }

        const previousState = clone(state);
        const previousSession = normalizeSessionRecord(session);
        state.users = state.users.map((user) =>
          user.email === target ? { ...user, active: !user.active } : user,
        );
        try {
          await persistStateToCloudNow({
            skipRender: true,
          });
          setFlash("success", "Account status updated.");
        } catch (error) {
          if (error?.code !== "stale_revision") {
            state = previousState;
          }
          session = previousSession;
          setFlash(
            error?.code === "stale_revision" ? "warning" : "error",
            error?.message || "The account status could not be saved to the shared system.",
          );
        }

        saveState();
        saveSession();
        renderApp();
      }

      async function deleteUser(email) {
        if (!canAccessGlobalSettings()) {
          setFlash("error", "Only System Managers can remove user accounts.");
          renderApp();
          return;
        }

        const target = normalizeEmail(email);
        if (isProtectedSystemManagerEmail(target)) {
          setFlash("error", "The last active System Manager cannot be deleted.");
          renderApp();
          return;
        }
        const previousState = clone(state);
        const previousSession = normalizeSessionRecord(session);

        removePasswordFromDeviceVault(target);
        if (normalizeEmail(authPrefs?.rememberedEmail) === target) {
          authPrefs = normalizeAuthPrefs({
            rememberedEmail: "",
            savePasswordOnDevice: false,
          });
          saveAuthPrefs();
        }

        state.users = state.users.filter((user) => user.email !== target);
        state.recoveryRequests = (state.recoveryRequests || []).map((request) =>
          normalizeEmail(request.email) === target
            ? {
                ...request,
                status: "resolved",
                resolvedAt: timestamp(),
                resolvedBy: normalizeEmail(session.userEmail),
              }
            : request,
        );
        state.tournaments = state.tournaments.map((tournament) => {
          const updatedPermissions = normalizeTournamentPermissions(tournament.permissions || {});
          getTournamentPermissionKeys({ includeLegacy: true }).forEach((key) => {
            updatedPermissions[key] = (updatedPermissions[key] || []).filter((entry) => entry !== target);
          });
          return addAudit(
            {
              ...tournament,
              permissions: updatedPermissions,
            },
            "Removed user account " + target + " from the platform directory.",
          );
        });

        if (normalizeEmail(session.userEmail) === target) {
          session.userEmail = "";
          session.view = "overview";
          session.managedTournamentId = "";
        }

        try {
          await persistStateToCloudNow({
            skipRender: true,
          });
          setFlash("success", "User removed from the database.");
        } catch (error) {
          if (error?.code !== "stale_revision") {
            state = previousState;
          }
          session = previousSession;
          setFlash(
            error?.code === "stale_revision" ? "warning" : "error",
            error?.message || "The account removal could not be saved to the shared system.",
          );
        }

        saveState();
        saveSession();
        renderApp();
      }

      function updateBranding(formData) {
        if (!canAccessGlobalSettings()) {
          setFlash("error", "Only System Managers can update global settings.");
          renderApp();
          return;
        }

        state.appSettings.branding.appName = String(formData.get("appName") || "").trim();
        state.appSettings.branding.subtitle = String(formData.get("subtitle") || "").trim();
        state.appSettings.branding.accent = String(formData.get("accent") || "").trim();
        state.appSettings.branding.accentDeep = String(formData.get("accentDeep") || "").trim();
        persist("success", "Branding settings saved.");
      }

      function updateUserPreferences(formData) {
        const currentUser = getCurrentUser();
        if (!currentUser) {
          setFlash("error", "Sign in again before changing personal settings.");
          renderApp();
          return;
        }

        const preferredLandingView = String(
          formData.get("preferredLandingView") || "overview",
        ).trim();
        const allowedLandingViews = getAllowedLandingViews(currentUser.email);

        state.users = state.users.map((user) =>
          normalizeEmail(user.email) === normalizeEmail(currentUser.email)
            ? {
                ...user,
                preferredLandingView: allowedLandingViews.includes(preferredLandingView)
                  ? preferredLandingView
                  : "overview",
              }
            : user,
        );

        persist("success", "Personal workspace settings saved.");
      }

      async function updateDevicePasswordPreference(formData) {
        const currentUser = getCurrentUser();
        if (!currentUser) {
          setFlash("error", "Sign in again before changing password-saving preferences.");
          renderApp();
          return;
        }

        const shouldSavePassword = boolFromForm(formData, "savePasswordOnDevice");
        const currentPassword = String(formData.get("currentPassword") || "");

        if (!shouldSavePassword) {
          updateAuthPrefsAfterCredentialChoice(currentUser.email, false);
          removePasswordFromDeviceVault(currentUser.email);
          await reduceDevicePasswordAutoSignIn();
          setFlash(
            "success",
            "JADE Hummingbird will stop remembering your device password preference for this account. If you want to fully delete a saved password, remove it from your browser or device password manager too.",
          );
          renderApp();
          return;
        }

        if (!supportsDevicePasswordSaving()) {
          setFlash(
            "error",
            "This browser does not support secure in-app device password saving.",
          );
          renderApp();
          return;
        }

        if (!currentPassword) {
          setFlash("error", "Enter your current password before saving it on this device.");
          renderApp();
          return;
        }

        const passwordCheck = await verifyUserPassword(currentUser, currentPassword);
        if (!passwordCheck.ok) {
          setFlash("error", "That current password is incorrect.");
          renderApp();
          return;
        }

        if (passwordCheck.needsUpgrade) {
          Object.assign(currentUser, await buildSecurePasswordRecord(currentPassword));
          saveState();
        }

        updateAuthPrefsAfterCredentialChoice(currentUser.email, true);
        await savePasswordToDeviceVault(currentUser.email, currentPassword);
        await saveBrowserCredential(currentUser.name, currentUser.email, currentPassword);
        setFlash(
          "success",
          "Your password-saving preference has been updated for this device.",
        );
        renderApp();
      }

