            queueFocusedTournamentSectionJump(
              session.managedTournamentId,
              session.focusedTournamentSection,
            );
            if (session.focusedTournamentSection !== "results") {
              session.resultsStudioView = "wins";
            }
            clearFlash();
            saveSession();
            requestSessionHistoryPush();
            renderApp();
